/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export type DeployStatusState = "queued" | "building" | "ready" | "failed" | "canceled"

export type DeployEnvironment = "preview" | "production"

export type DeployStepState = "queued" | "running" | "done" | "failed" | "canceled" | "skipped"

export interface DeployStep {
  id: string
  /** "Install dependencies", "Build", "Run tests", "Deploy". */
  name: string
  status: DeployStepState
  /** Final run time in ms, shown once the step ends. */
  durationMs?: number
  /** Epoch ms when the step started. Drives its live elapsed counter. */
  startedAt?: number
  /** Raw log, ANSI escape codes included. The running step tails it live. */
  log?: string
}

export interface DeployPrevious {
  /** Commit sha of the deploy to go back to. Shown as seven characters. */
  commit: string
  /** Optional label, for example "Yesterday 17:42". */
  label?: string
}

export interface DeployStatusProps extends Omit<React.ComponentProps<"div">, "title"> {
  status: DeployStatusState
  /** Preview or production. Production deploys offer a rollback once ready. */
  environment?: DeployEnvironment
  /** Commit sha. Shown as seven characters, copied in full. */
  commit?: string
  /** Subject line of the commit, shown after the sha. */
  commitMessage?: string
  branch?: string
  steps?: DeployStep[]
  /** Deployment URL. Shown with copy and open once the deploy is ready. */
  url?: string
  /** Epoch ms when the deploy started. Drives the total elapsed counter. */
  startedAt?: number
  /** Total run time in ms. Defaults to the sum of the step durations. */
  durationMs?: number
  /** What went wrong and how to fix it. Shown when `status` is `failed`. */
  errorText?: React.ReactNode
  /** The deploy a rollback returns to. Rollback shows for ready production deploys and failures. */
  previousDeploy?: DeployPrevious
  /** Shows Cancel deploy while queued or building. */
  onCancel?: () => void
  /** Shows Redeploy after a failure or cancel. */
  onRetry?: () => void
  /** Called after the user confirms the rollback in place. */
  onRollback?: (previous: DeployPrevious) => void
  /** The rollback is running: the button shows a spinner. */
  rollingBack?: boolean
  /** Replaces the header label, for example "Promoting to production". */
  title?: React.ReactNode
  /** Height cap of the live log tail. Number means px. Default 168. */
  logMaxHeight?: number | string
  /** `card` draws its own surface; `plain` sits inside one you already have. */
  variant?: "card" | "plain"
  /** Extra controls at the start of the footer. */
  actions?: React.ReactNode
}

/* -------------------------------------------------------------------------------------------------
 * DeployStatusInline: one line for a chat message
 * -----------------------------------------------------------------------------------------------*/

export interface DeployStatusInlineProps
  extends Omit<React.ComponentProps<"div">, "title">,
    Pick<
      DeployStatusProps,
      "status" | "environment" | "steps" | "url" | "startedAt" | "durationMs" | "branch" | "onRetry"
    > {
  /** Replaces the label. */
  title?: React.ReactNode
  /** Makes the line a button, for example to open the full pipeline. */
  onOpenDetails?: () => void
}

interface UseChatcnElapsedOptions {
  /** True while the timed work is happening. */
  running: boolean
  /** Epoch ms when the work started. Measured from the first `running` render when omitted. */
  startedAt?: number
  /** Final duration from the runtime. Wins over the measured one once `running` is false. */
  durationMs?: number
}

interface UseChatcnElapsedResult {
  /** Live elapsed ms while running, the final duration afterwards, `undefined` when unknown. */
  ms: number | undefined
  running: boolean
}

/**
 * Elapsed time for a step, a run or a reasoning block.
 *
 * Ticks once per second, aligned to the start time so the counter turns over exactly at 1 s,
 * 2 s and so on, never at random offsets. A counter that changes faster only adds noise.
 */
function useChatcnElapsed({
  running,
  startedAt,
  durationMs,
}: UseChatcnElapsedOptions): UseChatcnElapsedResult {
  const [autoStart, setAutoStart] = React.useState<number>()
  const [measured, setMeasured] = React.useState<number>()
  // Starts empty and reads the clock after mount: a render must not read it (Next.js prerender).
  const [now, setNow] = React.useState<number | null>(null)
  const start = startedAt ?? autoStart

  // Record our own start when the caller gives none. A new run (running again) starts over.
  React.useEffect(() => {
    if (!running) return
    if (startedAt === undefined) setAutoStart((prev) => prev ?? Date.now())
    setMeasured(undefined)
    setNow(Date.now())
  }, [running, startedAt])

  // Freeze the measured duration when the work stops.
  const wasRunning = React.useRef(running)
  React.useEffect(() => {
    if (wasRunning.current && !running && start !== undefined) {
      setMeasured(Date.now() - start)
      setAutoStart(undefined)
    }
    wasRunning.current = running
  }, [running, start])

  React.useEffect(() => {
    if (!running || start === undefined) return
    let id: number
    const schedule = () => {
      const elapsed = Date.now() - start
      // Next whole-second boundary, plus a few ms so rounding never shows the old second.
      const wait = 1000 - (((elapsed % 1000) + 1000) % 1000) + 8
      id = window.setTimeout(() => {
        setNow(Date.now())
        schedule()
      }, wait)
    }
    schedule()
    return () => window.clearTimeout(id)
  }, [running, start])

  if (running)
    return { ms: start === undefined ? undefined : Math.max(0, (now ?? start) - start), running }
  return { ms: durationMs ?? measured, running }
}

function summedDuration(steps: DeployStep[] | undefined) {
  if (!steps?.length) return undefined
  let total = 0
  let any = false
  for (const step of steps) {
    if (step.durationMs !== undefined) {
      total += step.durationMs
      any = true
    }
  }
  return any ? total : undefined
}

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

const ENV_NAME: Record<DeployEnvironment, string> = { preview: "Preview", production: "Production" }

function failedStep(steps: DeployStep[] | undefined) {
  return steps?.find((s) => s.status === "failed")
}

function currentStep(steps: DeployStep[] | undefined) {
  return steps?.find((s) => s.status === "running")
}

const NBSP = " "

/**
 * Formats a duration the chatcn way: numerals, a non-breaking space before the unit.
 * `precise` (the default) keeps a decimal under 10 s and milliseconds under 1 s, for finished
 * steps. Turn it off for live counters and "Thought for 12 s", which read in whole seconds.
 */
function formatChatcnDuration(ms: number, { precise = true }: { precise?: boolean } = {}) {
  const safe = Math.max(0, ms)
  if (precise && safe < 1000) return `${Math.max(1, Math.round(safe))}${NBSP}ms`
  const s = safe / 1000
  if (precise && s < 10) return `${s.toFixed(1)}${NBSP}s`
  if (s < 60) return `${precise ? Math.round(s) : Math.floor(s)}${NBSP}s`
  const totalS = Math.floor(s)
  const h = Math.floor(totalS / 3600)
  const m = Math.floor((totalS % 3600) / 60)
  const rest = totalS % 60
  if (h > 0) return `${h}${NBSP}h ${m}${NBSP}m`
  return `${m}${NBSP}m ${rest}${NBSP}s`
}

/** `https://host/path/` reads as `host/path`: the protocol is noise in a status line. */
function displayUrl(url: string) {
  return url.replace(/^https?:\/\//, "").replace(/\/$/, "")
}

/* -------------------------------------------------------------------------------------------------
 * Glyphs: one vocabulary for the deploy and its steps. The hue backs up the shape and the label.
 * -----------------------------------------------------------------------------------------------*/

type GlyphKind = "queued" | "running" | "done" | "failed" | "canceled" | "skipped"

const GLYPH_TONE: Record<GlyphKind, string> = {
  queued: "text-(color:--chatcn-fg-subtle)",
  running: "text-(color:--chatcn-blue)",
  done: "text-(color:--chatcn-green)",
  failed: "text-(color:--chatcn-red)",
  canceled: "text-(color:--chatcn-fg-subtle)",
  skipped: "text-(color:--chatcn-fg-faint)",
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

