function glyphFor(kind: GlyphKind) {
  switch (kind) {
    case "queued":
      return <CircleDashedIcon />
    case "running":
      return <Spinner className="size-4" />
    case "done":
      return <CircleCheckIcon />
    case "failed":
      return <CircleXIcon />
    case "canceled":
      return <CircleStopIcon />
    case "skipped":
      return <CircleMinusIcon />
  }
}

/** Status glyph. Swaps with the kit's blur crossfade so queued to ready reads as one object. */
function DeployGlyph({ kind, className }: { kind: GlyphKind; className?: string }) {
  return (
    <span
      aria-hidden="true"
      data-slot="deploy-status-glyph"
      className={cn(
        "grid size-4 shrink-0 place-items-center [&_svg]:size-4",
        GLYPH_TONE[kind],
        className,
      )}
    >
      <span
        key={kind}
        className="grid place-items-center motion-safe:animate-[chatcn-swap_150ms_var(--chatcn-ease-out)]"
      >
        {glyphFor(kind)}
      </span>
    </span>
  )
}

const KIND_OF: Record<DeployStatusState, GlyphKind> = {
  queued: "queued",
  building: "running",
  ready: "done",
  failed: "failed",
  canceled: "canceled",
}

type ButtonVariant = "solid" | "outline" | "ghost" | "subtle"

type ButtonSize = "xs" | "sm" | "md" | "lg" | "icon-xs" | "icon-sm" | "icon-md" | "icon-lg"

const base = cn(
  "chatcn-focus inline-flex shrink-0 items-center justify-center gap-1.5 font-medium whitespace-nowrap select-none",
  "ease-(--chatcn-ease-standard) transition-[background-color,color,box-shadow,scale] duration-150",
  "active:scale-(--chatcn-press-scale) active:duration-100 disabled:pointer-events-none disabled:opacity-50",
