export function DeployStatusInline({
  status,
  environment = "preview",
  steps,
  url,
  startedAt,
  durationMs,
  branch,
  onRetry,
  title,
  onOpenDetails,
  className,
  ...props
}: DeployStatusInlineProps) {
  const building = status === "building"
  const { ms } = useChatcnElapsed({
    running: building,
    startedAt,
    durationMs: durationMs ?? summedDuration(steps),
  })
  const name = ENV_NAME[environment]
  const failed = failedStep(steps)
  const running = currentStep(steps)

  const label =
    status === "building"
      ? `Building${ms !== undefined && ms >= 1000 ? ` ${formatChatcnDuration(ms, { precise: false })}` : ""}`
      : status === "ready"
        ? `${name} ready`
        : status === "failed"
          ? failed
            ? `${failed.name} failed`
            : "Deploy failed"
          : status === "queued"
            ? `${name} deploy queued`
            : "Deploy canceled"

  const detail =
    status === "ready" && url ? (
      <span dir="ltr" className="truncate font-mono">
        {displayUrl(url)}
      </span>
    ) : status === "building" && running ? (
      <span className="truncate">{running.name}</span>
    ) : branch ? (
      <span className="truncate font-mono">{branch}</span>
    ) : null

  const text = (
    <>
      <DeployGlyph kind={KIND_OF[status]} />
      <span
        className={cn(
          "text-[0.8125rem]/[1.25rem] shrink-0 font-medium tabular-nums [unicode-bidi:plaintext]",
          status === "failed" && "text-(color:--chatcn-red)",
        )}
      >
        {title ?? label}
      </span>
      {detail ? (
        <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex min-w-0 items-center">
          {detail}
        </span>
      ) : null}
    </>
  )

  return (
    <div
      data-slot="deploy-status-inline"
      data-deploy-status-state={status}
      data-environment={environment}
      className={cn(
        "bg-(color:--chatcn-card) shadow-(--chatcn-shadow-border) rounded-(--chatcn-radius-md) inline-flex h-8 max-w-full min-w-0 items-center gap-2 ps-2.5 pe-1",
        "forced-colors:outline-1 forced-colors:outline-solid",
        !(status === "ready" && url) && !(status === "failed" && onRetry) && "pe-2.5",
        className,
      )}
      {...props}
    >
      {onOpenDetails ? (
        <button
          type="button"
          onClick={onOpenDetails}
          className="chatcn-focus rounded-(--chatcn-radius-xs) -ms-1 flex min-w-0 items-center gap-2 ps-1 text-start outline-none"
        >
          {text}
        </button>
      ) : (
        text
      )}
      {status === "ready" && url ? (
        <a
          href={url}
          target="_blank"
          rel="noreferrer"
          aria-label={environment === "production" ? "Open site" : "Open preview"}
          className={cn(buttonVariants({ size: "icon-xs" }), "pointer-coarse:size-11")}
        >
          <ExternalLinkIcon className="rtl:-scale-x-100" />
        </a>
      ) : null}
      {status === "failed" && onRetry ? (
        <Button
          size="icon-xs"
          aria-label="Redeploy"
          onClick={onRetry}
          className="pointer-coarse:size-11"
        >
          <RotateCcwIcon />
        </Button>
      ) : null}
      <span aria-live="polite" className="sr-only">
        {status === "ready" || status === "failed" || status === "canceled" ? label : ""}
      </span>
    </div>
  )
}

function headerLabel(status: DeployStatusState, env: DeployEnvironment, steps?: DeployStep[]) {
  const name = ENV_NAME[env]
  switch (status) {
    case "queued":
      return `${name} deploy queued`
    case "building":
      return `Building ${name.toLowerCase()}`
    case "ready":
      return env === "production" ? "Deployed to production" : "Preview ready"
    case "failed": {
      const step = failedStep(steps)
      return step ? `${step.name} failed` : "Deploy failed"
    }
    case "canceled":
      return "Deploy canceled"
  }
}

