function StepTime({ step }: { step: DeployStep }) {
  const running = step.status === "running"
  const { ms } = useChatcnElapsed({
    running,
    startedAt: step.startedAt,
    durationMs: step.durationMs,
  })
  let text: string
  if (running)
    text = ms !== undefined && ms >= 1000 ? formatChatcnDuration(ms, { precise: false }) : "Running"
  else if ((step.status === "done" || step.status === "failed") && ms !== undefined)
    text = formatChatcnDuration(ms)
  else text = step.status === "queued" ? "" : STEP_WORD[step.status]
  return (
    <span
      dir="ltr"
      className={cn(
        "text-[0.75rem]/[1rem] shrink-0 tabular-nums",
        step.status === "failed" ? "text-(color:--chatcn-red)" : "text-(color:--chatcn-fg-subtle)",
      )}
    >
      {text}
      {/* The state in words when the time stands in for it, so the row's name is what it shows
          plus the state: "Build 32 s, failed". */}
      {text === STEP_WORD[step.status] ? null : (
        <span className="sr-only">{`, ${STEP_WORD[step.status].toLowerCase()}`}</span>
      )}
    </span>
  )
}

