/**
 * A deployment the agent started: the overall status and time, each step with its duration, a
 * live log tail for the running step, the URL once ready, and Cancel, Redeploy or Roll back.
 */
export function DeployStatus({
  status,
  environment = "preview",
  commit,
  commitMessage,
  branch,
  steps,
  url,
  startedAt,
  durationMs,
  errorText,
  previousDeploy,
  onCancel,
  onRetry,
  onRollback,
  rollingBack,
  title,
  logMaxHeight = 168,
  variant = "card",
  actions,
  className,
  ...props
}: DeployStatusProps) {
  const building = status === "building"
  const total = useChatcnElapsed({
    running: building,
    startedAt,
    durationMs: durationMs ?? summedDuration(steps),
  })
  const [confirming, setConfirming] = React.useState(false)
  const label = headerLabel(status, environment, steps)
  const short = commit?.slice(0, 7)

  const totalText =
    status === "queued" || status === "canceled"
      ? null
      : total.ms === undefined
        ? null
        : building
          ? formatChatcnDuration(total.ms, { precise: false })
          : formatChatcnDuration(total.ms)

  const canRollback =
    Boolean(onRollback && previousDeploy) &&
    ((status === "ready" && environment === "production") || status === "failed")
  const canCancel = Boolean(onCancel) && (status === "queued" || building)
  const canRetry = Boolean(onRetry) && (status === "failed" || status === "canceled")
  const hasFooter = canRollback || canCancel || canRetry || Boolean(actions)

  const announcement =
    status === "ready"
      ? `${label}${url ? ` at ${displayUrl(url)}` : ""}`
      : status === "failed" || status === "canceled"
        ? label
        : ""

  return (
    <div
      data-slot="deploy-status"
      data-deploy-status-state={status}
      data-environment={environment}
      data-variant={variant}
      aria-busy={building || undefined}
      className={cn(
        "text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) flex min-w-0 flex-col",
        variant === "card" &&
          "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) overflow-hidden forced-colors:outline-1 forced-colors:outline-solid",
        className,
      )}
      {...props}
    >
      {/* Header: status, then what is being deployed. */}
      <div className="flex flex-col pb-2">
        <div className="flex h-10 min-w-0 items-center gap-2.5 ps-3.5 pe-3.5 pointer-coarse:h-11">
          <DeployGlyph kind={KIND_OF[status]} />
          <span className="min-w-0 flex-1 truncate font-medium">
            {title ??
              (building ? (
                <ShimmerText>{label}</ShimmerText>
              ) : (
                <span className={status === "failed" ? "text-(color:--chatcn-red)" : undefined}>{label}</span>
              ))}
          </span>
          {totalText ? (
            <span dir="ltr" className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0 tabular-nums">
              {totalText}
            </span>
          ) : null}
        </div>
        {branch || short || commitMessage ? (
          <div className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) -mt-1.5 flex min-w-0 items-center gap-x-3 ps-[2.625rem] pe-3.5 [&_svg]:size-3.5">
            <span className="shrink-0">{ENV_NAME[environment]}</span>
            {branch ? (
              <span className="flex max-w-[45%] min-w-0 shrink-0 items-center gap-1">
                <GitBranchIcon aria-hidden="true" className="shrink-0" />
                <span className="text-(color:--chatcn-fg-muted) truncate font-mono">{branch}</span>
              </span>
            ) : null}
            {short ? (
              <span className="flex min-w-0 flex-1 items-center gap-1">
                <GitCommitHorizontalIcon aria-hidden="true" className="shrink-0" />
                <span className="text-(color:--chatcn-fg-muted) shrink-0 font-mono tabular-nums">
                  {short}
                </span>
                {commitMessage ? <span className="ms-1 truncate">{commitMessage}</span> : null}
              </span>
            ) : null}
          </div>
        ) : null}
      </div>

      {steps && steps.length > 0 ? (
        <ol aria-label="Deploy steps" className="flex flex-col px-1.5 pb-1.5">
          {steps.map((step) => (
            <DeployStepRow key={step.id} step={step} logMaxHeight={logMaxHeight} />
          ))}
        </ol>
      ) : null}

      {status === "ready" && url ? (
        <div
          data-slot="deploy-status-url"
          className="bg-(color:--chatcn-inset) rounded-(--chatcn-radius-md) mx-3.5 mb-3.5 flex h-9 min-w-0 items-center gap-2 ps-3 pe-1"
        >
          <GlobeIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle) size-3.5 shrink-0" />
          <a
            href={url}
            target="_blank"
            rel="noreferrer"
            dir="ltr"
            className="chatcn-focus text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) rounded-(--chatcn-radius-xs) min-w-0 flex-1 truncate font-mono underline-offset-2 hover:underline"
          >
            {displayUrl(url)}
          </a>
          <Tooltip content="Copy URL">
            <CopyButton
              size="icon-sm"
              value={url}
              label="Copy URL"
              className="pointer-coarse:size-11"
            />
          </Tooltip>
          <Tooltip content={environment === "production" ? "Open site" : "Open preview"}>
            <a
              href={url}
              target="_blank"
              rel="noreferrer"
              aria-label={environment === "production" ? "Open site" : "Open preview"}
              className={cn(buttonVariants({ size: "icon-sm" }), "pointer-coarse:size-11")}
            >
              <ExternalLinkIcon className="rtl:-scale-x-100" />
            </a>
          </Tooltip>
        </div>
      ) : null}

      {status === "failed" && errorText ? (
        <div
          data-slot="deploy-status-error"
          className={cn(
            "rounded-(--chatcn-radius-md) bg-(color:--chatcn-red-bg) mx-3.5 mb-3.5 px-3 py-2",
            "text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) text-pretty",
          )}
        >
          {errorText}
        </div>
      ) : null}

      {hasFooter ? (
        <div className="border-(color:--chatcn-border) flex min-h-10 items-center gap-1.5 border-t px-2 py-1.5">
          {confirming ? null : actions}
          {canRollback && previousDeploy && onRollback ? (
            <RollbackControl
              previous={previousDeploy}
              onRollback={onRollback}
              rollingBack={rollingBack}
              environment={environment}
              onConfirmingChange={setConfirming}
            />
          ) : null}
          {confirming ? null : (
            <>
              <span className="flex-1" />
              {canCancel ? (
                <Button size="sm" className="pointer-coarse:h-11" onClick={onCancel}>
                  <CircleStopIcon />
                  Cancel deploy
                </Button>
              ) : null}
              {canRetry ? (
                <Button size="sm" variant="solid" className="pointer-coarse:h-11" onClick={onRetry}>
                  <RotateCcwIcon />
                  Redeploy
                </Button>
              ) : null}
            </>
          )}
        </div>
      ) : null}

      {/* Announce the outcome once, never each step or tick. */}
      <span aria-live="polite" className="sr-only">
        {announcement}
      </span>
    </div>
  )
}

export default DeployStatus

