/** Shared content for the deploy-status examples: brightwell/console, PR 482. */

const COMMIT = "8f3c2a91d4be07c5a2e6f13b9d0c7e44a1b5f290"

const COMMIT_MESSAGE = "Paginate the runs list"

const BRANCH = "feat/runs-pagination"

const PREVIEW_URL = "https://console-git-feat-runs-pagination.brightwell.dev"

/** Queued, then each step runs with its log tailing live, then the preview lands. Replays. */
function DeployStatusDemo() {
  const [status, setStatus] = React.useState<DeployStatusState>("queued")
  const [active, setActive] = React.useState(-1)
  const [shown, setShown] = React.useState(0)
  const [stepStart, setStepStart] = React.useState(0)
  const [runStart, setRunStart] = React.useState(0)

  React.useEffect(() => {
    let id: number
    if (status === "queued") {
      id = window.setTimeout(() => {
        const now = Date.now()
        setRunStart(now - (PLAN[0]?.offset ?? 0))
        setStepStart(now - (PLAN[0]?.offset ?? 0))
        setActive(0)
        setShown(0)
        setStatus("building")
      }, 1400)
    } else if (status === "building") {
      const step = PLAN[active]
      if (!step) return
      if (shown < step.lines.length) {
        id = window.setTimeout(() => setShown((n) => n + 1), step.ms / step.lines.length)
      } else {
        id = window.setTimeout(() => {
          const next = active + 1
          if (next >= PLAN.length) {
            setStatus("ready")
            return
          }
          // The header total reads as the finished steps plus the one now running.
          const done = readySteps.slice(0, next).reduce((t, s) => t + (s.durationMs ?? 0), 0)
          const now = Date.now()
          setRunStart(now - done - (PLAN[next]?.offset ?? 0))
          setStepStart(now - (PLAN[next]?.offset ?? 0))
          setActive(next)
          setShown(0)
        }, 400)
      }
    } else {
      id = window.setTimeout(() => {
        setActive(-1)
        setShown(0)
        setStatus("queued")
      }, 5000)
    }
    return () => window.clearTimeout(id)
  }, [status, active, shown])

  const steps: DeployStep[] = readySteps.map((step, i) => {
    if (status === "ready") return step
    if (status === "queued" || i > active) return { id: step.id, name: step.name, status: "queued" }
    if (i < active) return step
    return {
      id: step.id,
      name: step.name,
      status: "running",
      startedAt: stepStart,
      log: PLAN[i]?.lines.slice(0, shown).join("\n") ?? "",
    }
  })

  return (
    <DeployStatus
      className="w-full max-w-lg"
      status={status}
      environment="preview"
      commit={COMMIT}
      commitMessage={COMMIT_MESSAGE}
      branch={BRANCH}
      steps={steps}
      startedAt={status === "building" ? runStart : undefined}
      url={PREVIEW_URL}
      onCancel={() => {
        setActive(-1)
        setStatus("queued")
      }}
    />
  )
}

/** The line under each 21st demo that points back to the kit. */
function MoreOn({ slug, children }: { slug: string; children: React.ReactNode }) {
  return (
    <p data-fit-hide className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-faint) text-center text-balance">
      {children}{" "}
      <a
        href={`https://chatcn.dev/docs/components/${slug}`}
        target="_blank"
        rel="noopener"
        className="text-(color:--chatcn-fg-subtle) hover:text-(color:--chatcn-fg) underline underline-offset-2"
      >
        chatcn.dev
      </a>
    </p>
  )
}

/** The kit's own example, framed for the 21st preview. */
export default function DeployStatusPreview() {
  return (
    <FitFrame minWidth="38rem">
      <div className="flex w-full flex-col items-center justify-center gap-4 p-6">
        <div className="flex w-full max-w-2xl justify-center">
          <DeployStatusDemo />
        </div>
        <MoreOn slug="deploy-status">Deploys from queued to ready, with live logs per step. On</MoreOn>
      </div>
    </FitFrame>
  )
}
